mapper.select:
SELECT id, user_id, idempotency_key, request_hash, status, response_json, created_at, updated_at
FROM chat_request_idempotency
WHERE user_id = #{userId}
  AND idempotency_key = #{idempotencyKey}
LIMIT 1

mapper.update:
