SET status = 'SUCCESS',
    response_json = #{responseJson},
    updated_at = NOW(3)
WHERE user_id = #{userId}
  AND idempotency_key = #{idempotencyKey}
  AND request_hash = #{requestHash}
  AND status = 'PENDING'

